#include <cassert>
#include <vector>
#include <unordered_map>
#include <algorithm>
#include <climits>
#include <utility>

using namespace std;

void test() {
    // Test Case 1: Simple satisfiable case
    {
        ConstraintSolver solver(3, 2);
        solver.add_constraint(0, 0, 1);  // Var 1 must be true
        solver.add_constraint(1, 1, -1); // Var 2 must be false

        auto [found, solution] = solver.solve();
        assert(found == true);
        assert(solution == vector<bool>({true, false, false}));
    }

    // Test Case 2: Conflicting constraints
    {
        ConstraintSolver solver(2, 2);
        solver.add_constraint(0, 0, 1);
        solver.add_constraint(1, 0, -1);

        auto [found, solution] = solver.solve();
        assert(found == false);
    }

    // Test Case 3: Larger problem
    {
        ConstraintSolver solver(5, 4);
        solver.add_constraint(0, 0, 1);
        solver.add_constraint(0, 1, -1);
        solver.add_constraint(1, 2, 1);
        solver.add_constraint(2, 3, -1);
        solver.add_constraint(3, 4, 1);

        auto [found, solution] = solver.solve();
        assert(found == true);
        assert(solution == vector<bool>({false, false, true, false, true}));
    }

    // Test Case 4: Minimal solution required
    {
        ConstraintSolver solver(4, 3);
        solver.add_constraint(0, 0, 1);
        solver.add_constraint(1, 1, 1);
        solver.add_constraint(2, 2, 1);

        auto [found, solution] = solver.solve();
        assert(found == true);
        assert(solution == vector<bool>({true, true, true, false}));
    }

    // Test Case 5: Heuristic method
    {
        ConstraintSolver solver(6, 5);
        solver.add_constraint(0, 0, 1);
        solver.add_constraint(1, 1, -1);
        solver.add_constraint(2, 2, 1);
        solver.add_constraint(3, 3, -1);
        solver.add_constraint(4, 4, 1);

        auto [found, solution] = solver.solve_heuristic();
        assert(found == false);
        assert(solution == vector<bool>({true, true, true, true, true, false}));
    }

    // Test Case 6: Complex constraints
    {
        ConstraintSolver solver(4, 4);
        solver.add_constraint(0, 0, 1);
        solver.add_constraint(0, 1, -1);
        solver.add_constraint(1, 1, 1);
        solver.add_constraint(2, 2, -1);
        solver.add_constraint(3, 3, 1);

        auto [found, solution] = solver.solve();
        assert(found == true);
        assert(solution == vector<bool>({true, true, false, true}));
    }

    // Test Case 7: Edge case - no constraints
    {
        ConstraintSolver solver(3, 0);

        auto [found, solution] = solver.solve();
        assert(found == true);
        assert(solution == vector<bool>({true, false, false}));
    }
}

int main() {
    test();
    return 0;
}

