#include <cassert>
#include <vector>
#include <string>
#include <map>
#include <stdexcept>
#include <algorithm>

void test() {
    // Test Case 1: Basic insertion and lookup
    {
        TrieMap<int> map;
        map["to"] = 7;
        map["tea"] = 3;
        map["ted"] = 4;
        map["ten"] = 12;

        assert(map["to"] == 7);
        assert(map["tea"] == 3);
        assert(map.contains("ted") == true);
        assert(map.size() == 4);
    }

    // Test Case 2: Prefix search
    {
        TrieMap<int> map;
        map["apple"] = 1;
        map["appetite"] = 2;
        map["application"] = 3;
        map["banana"] = 4;

        std::vector<std::string> keys = map.keysWithPrefix("app");
        std::vector<std::string> expected = {"appetite", "apple", "application"};
        assert(keys == expected);
    }

    // Test Case 3: Longest prefix match
    {
        TrieMap<std::string> map;
        map["hello"] = "world";
        map["hell"] = "fire";
        map["he"] = "she";

        assert(map.longestPrefixOf("helloworld") == "hello");
    }

    // Test Case 4: Removal of keys
    {
        TrieMap<int> map;
        map["test"] = 1;
        map["testing"] = 2;
        map["tester"] = 3;

        assert(map.size() == 3);
        map.remove("test");
        assert(map.size() == 2);
        assert(map.contains("test") == false);
    }

