#include <cassert>
#include <vector>
#include <string>
#include <map>
#include <cmath>
#include <iomanip>

using namespace std;

void test() {
    // Test Case 1: Basic Entity Creation
    {
        Entity entity;
        entity.set_position(Point(10, 20));
        assert(entity.get_position().x == 10.00f);
        assert(entity.get_position().y == 20.00f);
    }

    // Test Case 2: Physics Simulation
    {
        Entity entity;
        entity.set_position(Point(0, 0));
        entity.add_force(Point(10, 5));

        entity.update(0.1f);
        assert(abs(entity.get_position().x - 0.09f) < 0.01f);
        assert(abs(entity.get_position().y - 0.04f) < 0.01f);
        assert(abs(entity.get_velocity().x - 0.90f) < 0.01f);
        assert(abs(entity.get_velocity().y - 0.45f) < 0.01f);

        entity.update(0.1f);
        assert(abs(entity.get_position().x - 0.17f) < 0.01f);
        assert(abs(entity.get_position().y - 0.09f) < 0.01f);
        assert(abs(entity.get_velocity().x - 0.81f) < 0.01f);
        assert(abs(entity.get_velocity().y - 0.40f) < 0.01f);

        entity.update(0.1f);
        assert(abs(entity.get_position().x - 0.24f) < 0.01f);
        assert(abs(entity.get_position().y - 0.12f) < 0.01f);
        assert(abs(entity.get_velocity().x - 0.73f) < 0.01f);
        assert(abs(entity.get_velocity().y - 0.36f) < 0.01f);

        entity.update(0.1f);
        assert(abs(entity.get_position().x - 0.31f) < 0.01f);
        assert(abs(entity.get_position().y - 0.15f) < 0.01f);
        assert(abs(entity.get_velocity().x - 0.66f) < 0.01f);
        assert(abs(entity.get_velocity().y - 0.33f) < 0.01f);

        entity.update(0.1f);
        assert(abs(entity.get_position().x - 0.37f) < 0.01f);
        assert(abs(entity.get_position().y - 0.18f) < 0.01f);
        assert(abs(entity.get_velocity().x - 0.59f) < 0.01f);
        assert(abs(entity.get_velocity().y - 0.30f) < 0.01f);
    }

    // Test Case 3: Animation System
    {
        Entity entity;
        Animation walk("walk");
        walk.add_frame("frame1", 0.2f);
        walk.add_frame("frame2", 0.2f);
        walk.add_frame("frame3", 0.2f);
        entity.add_animation("walk", walk);
        entity.set_animation("walk");

        entity.update(0.1f);
        assert(entity.get_current_frame() == "frame1");

        entity.update(0.1f);
        assert(entity.get_current_frame() == "frame2");

        entity.update(0.1f);
        assert(entity.get_current_frame() == "frame2");

        entity.update(0.1f);
        assert(entity.get_current_frame() == "frame3");

        entity.update(0.1f);
        assert(entity.get_current_frame() == "frame3");
    }

    // Test Case 4: Collision Detection
    {
        Entity entity1, entity2;
        entity1.set_position(Point(0, 0));
        entity2.set_position(Point(30, 0));

        Hitbox hb(Point(), 32, 32);
        entity1.set_hitbox(hb);
        entity2.set_hitbox(hb);

        assert(entity1.check_collision(entity2) == true);

        entity2.set_position(Point(31, 0));
        assert(entity1.check_collision(entity2) == true);
    }

    // Test Case 5: Kinematic Object
    {
        Entity entity;
        entity.set_kinematic(true);
        entity.set_position(Point(0, 0));
        entity.add_force(Point(10, 0));
        entity.update(0.1f);

        assert(entity.get_position().x == 0.00f);
        assert(entity.get_position().y == 0.00f);
    }

    // Test Case 6: State Management
    {
        Entity entity;
        entity.set_state("idle");

        Animation idle("idle");
        idle.add_frame("idle_frame", 0.5f);
        entity.add_animation("idle", idle);

        Animation run("run");
        run.add_frame("run_frame1", 0.1f);
        run.add_frame("run_frame2", 0.1f);
        entity.add_animation("run", run);

        assert(entity.get_state() == "idle");
        assert(entity.get_current_frame() == "idle_frame");

        entity.set_state("run");
        entity.set_animation("run");
        entity.update(0.1f);

        assert(entity.get_current_frame() == "run_frame2");
    }

    // Test Case 7: Edge Case - Empty Animation
    {
        Entity entity;
        Animation empty("empty");
        entity.add_animation("empty", empty);
        entity.set_animation("empty");

        assert(entity.get_current_frame() == "missing_texture");
    }
}

int main() {
    test();
    return 0;
}

