#include <cassert>
#include <vector>
#include <string>
#include <map>
#include <memory>
#include <algorithm>
#include <stdexcept>

using namespace std;

void test() {
    // Test Case 1: Singleton pattern verification
    auto& game1 = GameManager::GetInstance();
    auto& game2 = GameManager::GetInstance();
    assert(&game1 == &game2);

    // Test Case 2: Level creation and switching
    Level* level1 = game1.AddLevel("Forest");
    Level* level2 = game1.AddLevel("Dungeon");
    assert(game1.LevelCount() == 2);
    assert(game1.CurrentLevel()->GetName() == "Forest");

    game1.LoadLevel(1);
    assert(game1.CurrentLevel()->GetName() == "Dungeon");

    // Test Case 3: Object management
    auto enemy = make_unique<GameObject>("Goblin", "Enemy");
    enemy->SetProperty("Health", "50");
    level2->AddObject(move(enemy));

    GameObject* found = game1.FindObject("Goblin");
    assert(found->name == "Goblin");
    assert(found->GetProperty("Health") == "50");

    game1.DestroyObject(found);
    assert(game1.FindObject("Goblin") == nullptr);

    // Test Case 4: Object cloning
    GameObject original("Chest", "Prop");
    original.SetProperty("Locked", "true");
    GameObject* clone = game1.SpawnCopy(&original);
    assert(original.name == "Chest");
    assert(original.GetProperty("Locked") == "true");
    assert(clone->name == "Chest");
    assert(clone->GetProperty("Locked") == "true");

    // Test Case 5: Tag-based search
    auto item1 = make_unique<GameObject>("Sword", "Item");
    auto item2 = make_unique<GameObject>("Potion", "Item");
    level2->AddObject(move(item1));
    level2->AddObject(move(item2));

    auto items = game1.FindObjectsByTag("Item");
    assert(items.size() == 2);
    assert(items[0]->name == "Sword" || items[0]->name == "Potion");
    assert(items[1]->name == "Sword" || items[1]->name == "Potion");
    assert(items[0]->name != items[1]->name);

    // Test Case 6: Global properties
    game1.SetGlobalProperty("Difficulty", "Hard");
    assert(game1.GetGlobalProperty("Difficulty") == "Hard");

    // Test Case 7: Empty level handling
    Level* emptyLevel = game1.AddLevel("Empty");
    game1.LoadLevel(2);
    assert(game1.CurrentLevel()->GetName() == "Empty");
    assert(game1.CurrentLevel()->ObjectCount() == 0);
    assert(game1.FindObject("Nothing") == nullptr);
}

int main() {
    test();
    return 0;
}

