#include <cassert>
#include <string>
#include <unordered_map>
#include <functional>
#include <vector>
#include <memory>

using namespace std;

void test() {
    // Test case 1: Basic button press
    {
        InputManager manager;
        manager.addButton("Fire");
        assert(manager.getButtonState("Fire") == Button::State::RELEASED);

        manager.pressButton("Fire");
        assert(manager.getButtonState("Fire") == Button::State::PRESSED);

        manager.updateAll();
        assert(manager.getButtonState("Fire") == Button::State::HELD);
        assert(manager.getButtonFramesHeld("Fire") == 2);
    }

    // Test case 2: Button release
    {
        InputManager manager;
        manager.addButton("Jump");
        manager.pressButton("Jump");
        manager.updateAll();
        assert(manager.getButtonState("Jump") == Button::State::HELD);

        manager.releaseButton("Jump");
        assert(manager.getButtonState("Jump") == Button::State::JUST_RELEASED);

        manager.updateAll();
        assert(manager.getButtonState("Jump") == Button::State::RELEASED);
    }

    // Test case 3: Multiple updates
    {
        InputManager manager;
        manager.addButton("Crouch");
        manager.pressButton("Crouch");

        for (int i = 0; i < 5; ++i) {
            manager.updateAll();
            assert(manager.getButtonState("Crouch") == Button::State::HELD);
            assert(manager.getButtonFramesHeld("Crouch") == i + 2);
        }
    }

    // Test case 4: Non-existent button
    {
        InputManager manager;
        assert(manager.getButtonState("Nonexistent") == Button::State::RELEASED);
    }

    // Test case 5: Button combo
    {
        InputManager manager;
        manager.addButton("X");
        manager.addButton("Y");

        bool comboTriggered = false;
        manager.addButtonCombo({"X", "Y"}, "XYCombo", [&]() {
            comboTriggered = true;
        });

        manager.pressButton("X");
        manager.checkCombos();
        assert(!comboTriggered);

        manager.pressButton("Y");
        manager.checkCombos();
        assert(comboTriggered);
    }

    // Test case 6: Multiple button combos
    {
        InputManager manager;
        manager.addButton("Up");
        manager.addButton("Down");
        manager.addButton("Left");
        manager.addButton("Right");

        int combo1Count = 0, combo2Count = 0;
        manager.addButtonCombo({"Up", "Down"}, "UpDown", [&]() { combo1Count++; });
        manager.addButtonCombo({"Left", "Right"}, "LeftRight", [&]() { combo2Count++; });

        manager.pressButton("Up");
        manager.pressButton("Down");
        manager.pressButton("Left");
        manager.checkCombos();
        assert(combo1Count == 1);
        assert(combo2Count == 0);

        manager.pressButton("Right");
        manager.checkCombos();
        assert(combo1Count == 1);
        assert(combo2Count == 1);
    }

    // Test case 7: Combo with held buttons
    {
        InputManager manager;
        manager.addButton("A");
        manager.addButton("B");
        manager.addButton("C");

        int comboCount = 0;
        manager.addButtonCombo({"A", "B", "C"}, "ABC", [&]() { comboCount++; });

        manager.pressButton("A");
        manager.updateAll(); // A becomes HELD
        manager.pressButton("B");
        manager.pressButton("C");
        manager.checkCombos();
        assert(comboCount == 1);
    }
}

int main() {
    test();
    return 0;
}

