private:
    bool CircleCircleCollision(const Collider& other) const;
    bool RectRectCollision(const Collider& other) const;
    bool CircleRectCollision(const Collider& rect) const;
    Vector2 GetRectCircleCollisionNormal(const Collider& circle) const;
};
```

## Requirements
1. Implement all member functions as shown in the class definitions
2. The collision detection should work for:
   - Circle-circle collisions
   - Rectangle-rectangle collisions
   - Circle-rectangle collisions (both ways)
3. For collisions, calculate the collision normal (direction vector) where applicable
4. Handle edge cases where shapes are exactly touching or one is inside another

## Example Usage
```cpp
int main() {
    // Create a circle collider at position (0,0) with radius 2
    Collider circle1(ColliderType::CIRCLE, Vector2(0, 0), Vector2(), 2.0f);

    // Create another circle collider at position (1,1) with radius 2
    Collider circle2(ColliderType::CIRCLE, Vector2(1, 1), Vector2(), 2.0f);

    // Check if they collide
    if (circle1.CheckCollision(circle2)) {
        Vector2 normal = circle1.GetCollisionNormal(circle2);
        cout << "Collision detected! Normal: (" << normal.x << ", " << normal.y << ")\n";
    }

    // Create a rectangle collider at (5,5) with size (4,4)
    Collider rect(ColliderType::RECTANGLE, Vector2(5, 5), Vector2(4, 4));

    // Check collision with circle
    Collider circle3(ColliderType::CIRCLE, Vector2(6, 6), Vector2(), 1.5f);
    if (rect.CheckCollision(circle3)) {
        Vector2 normal = rect.GetCollisionNormal(circle3);
        cout << "Rectangle-circle collision! Normal: (" << normal.x << ", " << normal.y << ")\n";
    }

    return 0;
}
```

## Constraints
1. All floating-point comparisons should use a small epsilon value (1e-5) to account for precision errors
2. The collision normal should always be a unit vector (magnitude = 1) when applicable
3. For rectangle-rectangle collisions, use axis-aligned bounding box (AABB) collision detection
4. For circle-rectangle collisions, find the closest point on the rectangle to the circle's center

## Notes
1. You don't need to implement polygon collision detection for this problem (the enum is provided for completeness)
2. Focus on making the collision detection accurate and efficient
3. The Vector2 struct should provide all necessary vector operations for the collision detection

