        agency.addObserver(&channel);

        for (int i = 1; i <= 5; i++) {
            agency.publishNews("Update " + std::to_string(i));
        }

        assert(channel.newsCount() == 5);
        assert(channel.getLatestNews() == "BREAKING: Update 5");
    }

    // Test case 6: Null observer
    {
        NewsAgency agency;
        agency.addObserver(nullptr);
        agency.publishNews("Test null observer");

        assert(agency.countObservers() == 0);
    }

    // Test case 7: Observer state clearing
    {
        NewsAgency agency;
        NewsChannel channel("Clear Test");
        agency.addObserver(&channel);
        agency.publishNews("First message");
        channel.clearNews();
        agency.publishNews("Second message");

        assert(channel.newsCount() == 1);
        assert(channel.getLatestNews() == "BREAKING: Second message");
    }
}

int main() {
    test();
    return 0;
}

