    AdvancedTimer timer(printTime, nullptr, AdvancedTimer::TimerMode::STEADY_CLOCK);

    // Simulate work
    for (int i = 0; i < 3; i++) {
        this_thread::sleep_for(chrono::milliseconds(100));
        timer.Lap(); // Record lap time
    }

    // Pause for a while
