    this_thread::sleep_for(chrono::milliseconds(200));
    timer.Resume();

    // Get statistics before stopping
    auto stats = timer.GetStatistics();
    cout << "Current elapsed: " << stats["elapsed"] << " ms" << endl;

    // Stop and automatically trigger callback
