        Vector3D rayDirection(0, 0, 1);
        auto result = cube.intersect(rayOrigin, rayDirection);

        assert(result.intersects == true);
        assert(fabs(result.distance - 1.0) < std::numeric_limits<double>::epsilon());
        assert(fabs(result.point.getX() - 0.0) < std::numeric_limits<double>::epsilon());
