        assert(fabs(result.normal.getY() - 0.0) < std::numeric_limits<double>::epsilon());
        assert(fabs(result.normal.getZ() - (-1.0)) < std::numeric_limits<double>::epsilon());
    }

    // Test Case 2: Ray missing the cube
    {
        Cube cube(Vector3D(-1, -1, -1), Vector3D(1, 1, 1));
        Vector3D rayOrigin(2, 2, -2);
