        assert(fabs(result.point.getZ() - (-1.0)) < std::numeric_limits<double>::epsilon());
        assert(fabs(result.normal.getX() - 0.0) < std::numeric_limits<double>::epsilon());
        assert(fabs(result.normal.getY() - 0.0) < std::numeric_limits<double>::epsilon());
        assert(fabs(result.normal.getZ() - (-1.0)) < std::numeric_limits<double>::epsilon());
    }

    // Test Case 4: Ray hitting edge of the cube
    {
        Cube cube(Vector3D(-1, -1, -1), Vector3D(1, 1, 1));
        Vector3D rayOrigin(1, 1, -2);
        Vector3D rayDirection(0, 0, 1);
        auto result = cube.intersect(rayOrigin, rayDirection);

        assert(result.intersects == false);
    }

    // Test Case 5: Non-axis aligned ray
    {
        Cube cube(Vector3D(-1, -1, -1), Vector3D(1, 1, 1));
        Vector3D rayOrigin(-2, -2, -2);
        Vector3D rayDirection(1, 1, 1);
        auto result = cube.intersect(rayOrigin, rayDirection);

        assert(result.intersects == true);
        assert(fabs(result.distance - 1.0) < std::numeric_limits<double>::epsilon());
        assert(fabs(result.point.getX() - (-1.0)) < std::numeric_limits<double>::epsilon());
        assert(fabs(result.point.getY() - (-1.0)) < std::numeric_limits<double>::epsilon());
        assert(fabs(result.point.getZ() - (-1.0)) < std::numeric_limits<double>::epsilon());
        assert(fabs(result.normal.getX() - (-1.0)) < std::numeric_limits<double>::epsilon());
        assert(fabs(result.normal.getY() - 0.0) < std::numeric_limits<double>::epsilon());
        assert(fabs(result.normal.getZ() - 0.0) < std::numeric_limits<double>::epsilon());
    }

    // Test Case 6: Zero volume cube
    {
        Cube cube(Vector3D(0, 0, 0), Vector3D(0, 0, 0));
        Vector3D rayOrigin(0, 0, -1);
