#include <cassert>
#include <cmath>
#include <cstring>

void test() {
    // Test 1: Identity matrix
    {
        AffineMatrix identity;
        Vector3 point(1.0f, 2.0f, 3.0f);
        Vector3 transformed = identity.transformPoint(point);
        assert(transformed.x == 1.0f && transformed.y == 2.0f && transformed.z == 3.0f);
    }

    // Test 2: Translation
    {
        AffineMatrix translation;
        translation.setTranslation(5.0f, -3.0f, 10.0f);
        Vector3 point(1.0f, 1.0f, 1.0f);
        Vector3 transformed = translation.transformPoint(point);
        assert(fabs(transformed.x - 6.0f) < 1e-6 && 
               fabs(transformed.y - (-2.0f)) < 1e-6 && 
               fabs(transformed.z - 11.0f) < 1e-6);
    }

    // Test 3: Uniform scaling
    {
        AffineMatrix scale;
        scale.setScale(2.5f);
        Vector3 point(1.0f, 2.0f, 3.0f);
        Vector3 transformed = scale.transformPoint(point);
        assert(fabs(transformed.x - 2.5f) < 1e-6 && 
               fabs(transformed.y - 5.0f) < 1e-6 && 
               fabs(transformed.z - 7.5f) < 1e-6);
    }

    // Test 4: Non-uniform scaling
    {
        AffineMatrix scale;
        scale.setScale(1.0f, 2.0f, 3.0f);
        Vector3 point(1.0f, 1.0f, 1.0f);
        Vector3 transformed = scale.transformPoint(point);
        assert(fabs(transformed.x - 1.0f) < 1e-6 && 
               fabs(transformed.y - 2.0f) < 1e-6 && 
               fabs(transformed.z - 3.0f) < 1e-6);
    }

    // Test 5: X-axis rotation
    {
        AffineMatrix rotation;
        rotation.setRotationX(90.0f);
        Vector3 vector(0.0f, 1.0f, 0.0f);
        Vector3 transformed = rotation.transformVector(vector);
        assert(fabs(transformed.x) < 1e-6 && 
               fabs(transformed.y) < 1e-6 && 
               fabs(transformed.z - 1.0f) < 1e-6);
    }

    // Test 6: Matrix multiplication
    {
        AffineMatrix translation;
        translation.setTranslation(10.0f, 20.0f, 30.0f);
        AffineMatrix scale;
        scale.setScale(2.0f);
        AffineMatrix combined = translation * scale;
        Vector3 point(1.0f, 1.0f, 1.0f);
        Vector3 transformed = combined.transformPoint(point);
        assert(fabs(transformed.x - 22.0f) < 1e-6 && 
               fabs(transformed.y - 42.0f) < 1e-6 && 
               fabs(transformed.z - 62.0f) < 1e-6);
    }

    // Test 7: Matrix inversion
    {
        AffineMatrix transform;
        transform.setTranslation(5.0f, 10.0f, 15.0f);
        transform.setRotationZ(45.0f);
        transform.setScale(2.0f);
        AffineMatrix inverse;
        memcpy(&inverse, &transform, sizeof(AffineMatrix));
        assert(inverse.invert());
        Vector3 point(1.0f, 2.0f, 3.0f);
        Vector3 transformed = transform.transformPoint(point);
        Vector3 restored = inverse.transformPoint(transformed);
        assert(fabs(restored.x - 1.0f) < 1e-6 && 
               fabs(restored.y - 2.0f) < 1e-6 && 
               fabs(restored.z - 3.0f) < 1e-6);
    }

    // Test 8: Decomposition
    {
        AffineMatrix transform;
        transform.setTranslation(5.0f, 10.0f, 15.0f);
        transform.setRotationY(30.0f);
        transform.setScale(2.0f, 3.0f, 4.0f);
        Vector3 translation, rotation, scale;
        transform.decompose(translation, rotation, scale);
        assert(fabs(translation.x - 0.0f) < 1e-6 && 
               fabs(translation.y - 0.0f) < 1e-6 && 
               fabs(translation.z - 0.0f) < 1e-6);
        assert(fabs(rotation.x - 0.0f) < 1e-6 && 
               fabs(rotation.y - 0.0f) < 1e-6 && 
               fabs(rotation.z - 0.0f) < 1e-6);
        assert(fabs(scale.x - 2.0f) < 1e-6 && 
               fabs(scale.y - 3.0f) < 1e-6 && 
               fabs(scale.z - 4.0f) < 1e-6);
    }
}

int main() {
    test();
    return 0;
}

samples.question:
# 3D Affine Transformations Matrix Problem

## Problem Description
Implement a class `AffineMatrix` that represents a 4x4 matrix for 3D affine transformations. The class should support various matrix operations including transformations (translation, rotation, scaling), matrix multiplication, inversion, transposition, and decomposition into translation, rotation, and scale components.

## Class Requirements
You must implement the following class exactly as specified:

```cpp
struct Vector3 {
    float x, y, z;
    Vector3(float x = 0, float y = 0, float z = 0) : x(x), y(y), z(z) {}
};

class AffineMatrix {
private:
    float m[16];

public:
    // Constructors
    AffineMatrix();
    AffineMatrix(const AffineMatrix& other);

    // Basic matrix operations
    void setIdentity();
    void setZero();
    void setScale(float s);
    void setScale(float sx, float sy, float sz);
    void setTranslation(float x, float y, float z);
    void setRotationX(float degrees);
    void setRotationY(float degrees);
    void setRotationZ(float degrees);

    // Matrix operations
    void multiply(const AffineMatrix& other);
    bool invert();
    void transpose();

    // Transformations
    Vector3 transformPoint(const Vector3& point) const;
    Vector3 transformVector(const Vector3& vector) const;

    // Advanced operations
    float getUniformScale() const;
    void decompose(Vector3& translation, Vector3& rotation, Vector3& scale) const;

    // Utility functions
    void print() const;

    // Operator overloading
    AffineMatrix operator*(const AffineMatrix& other) const;
    Vector3 operator*(const Vector3& point) const;
};
```

## Function Specifications

### Constructors
- `AffineMatrix()`: Creates an identity matrix
- `AffineMatrix(const AffineMatrix& other)`: Copy constructor

### Basic Matrix Operations
- `void setIdentity()`: Sets the matrix to identity
- `void setZero()`: Sets all elements to zero except m[15] which is set to 1
- `void setScale(float s)`: Sets uniform scaling
- `void setScale(float sx, float sy, float sz)`: Sets non-uniform scaling
- `void setTranslation(float x, float y, float z)`: Sets translation components
- `void setRotationX(float degrees)`: Sets rotation around X-axis
- `void setRotationY(float degrees)`: Sets rotation around Y-axis
- `void setRotationZ(float degrees)`: Sets rotation around Z-axis

### Matrix Operations
- `void multiply(const AffineMatrix& other)`: Multiplies this matrix by another matrix
- `bool invert()`: Inverts the matrix (returns false if not invertible)
- `void transpose()`: Transposes the matrix

### Transformations
- `Vector3 transformPoint(const Vector3& point) const`: Transforms a 3D point
- `Vector3 transformVector(const Vector3& vector) const`: Transforms a 3D vector (no translation)

### Advanced Operations
- `float getUniformScale() const`: Returns the uniform scale factor
- `void decompose(Vector3& translation, Vector3& rotation, Vector3& scale) const`: Decomposes the matrix into translation, rotation (in degrees), and scale components

### Utility Functions
- `void print() const`: Prints the matrix in readable format

### Operator Overloading
- `AffineMatrix operator*(const AffineMatrix& other) const`: Matrix multiplication
- `Vector3 operator*(const Vector3& point) const`: Transforms a point (same as transformPoint)

## Example Usage

```cpp
int main() {
    // Create a translation matrix
    AffineMatrix translation;
    translation.setTranslation(5.0f, 10.0f, 15.0f);

    // Create a rotation matrix
    AffineMatrix rotation;
    rotation.setRotationZ(45.0f);

    // Create a scaling matrix
    AffineMatrix scale;
    scale.setScale(2.0f);

    // Combine transformations
    AffineMatrix transform = translation * rotation * scale;

    // Transform a point
    Vector3 point(1.0f, 0.0f, 0.0f);
    Vector3 transformed = transform * point;

    // Print results
    std::cout << "Original point: (" << point.x << ", " << point.y << ", " << point.z << ")\n";
    std::cout << "Transformed point: (" << transformed.x << ", " << transformed.y << ", " << transformed.z << ")\n";

    // Decompose the matrix
    Vector3 t, r, s;
    transform.decompose(t, r, s);
    std::cout << "Decomposed:\n";
    std::cout << "  Translation: (" << t.x << ", " << t.y << ", " << t.z << ")\n";
    std::cout << "  Rotation: (" << r.x << ", " << r.y << ", " << r.z << ")\n";
    std::cout << "  Scale: (" << s.x << ", " << s.y << ", " << s.z << ")\n";

    return 0;
}
```

## Constraints
- All trigonometric calculations should use degrees (converted to radians internally)
- Matrix storage should follow column-major order (m[0], m[1], m[2], m[3] are first column)
- The matrix should maintain the affine property (last row should be [0, 0, 0, 1])
- Floating-point comparisons should use appropriate epsilon values (1e-6)

## Notes
- You may use standard C++ libraries including `<cmath>`, `<cstring>`, and `<stdexcept>`
- The value of π should be defined as `3.14159265358979323846f`
- The matrix should correctly handle all specified transformations and operations
